     tips = {"The whole pull on one button. From Defensive: press 1 = Battle Stance, press 2 = Charge, press 3 = back to Defensive, then Sunder Armor on every press.", "Bloodrage rides along in combat whenever it is ready (it is off the global cooldown): the swap back to Defensive is followed by 10 free Rage. Tactical Mastery (14) keeps 10 Rage through the swap.", "Too close to Charge? Keep pressing: you swing in Battle, and once the fight starts the next press goes Defensive.", "Before your level 10 stance quest it Sunders from Battle. Put Fight on the same bind on your Battle and Defensive bars."}},
    {name = "Fight", title = "Vanguard Charge / Sunder", icon = "ability_warrior_shieldcharge", lo = 25, hi = 60,
     body = "#showtooltip\n/targetenemy [noharm][dead]\n/startattack [harm,nodead]\n/cast [nocombat,stance:2,known:1310317,harm][nocombat,stance:1,harm] Charge; [nocombat,harm] Battle Stance; [combat,nostance:2] Defensive Stance; Sunder Armor\n/cast [combat] Bloodrage", pad = "RT+A", kb = "1",
     tips = {"With Vanguard you Charge straight from Defensive: no stance dance and you keep the Charge Rage. Without the talent it still dances (Battle, Charge, Defensive).", "In combat: Sunder Armor every press, with Bloodrage riding along whenever it is ready.", "After a kill one press selects the nearest enemy and Charges it.", "If Charge says Spell Not Learned or Must be in Battle Stance with Vanguard, tell us: Charge from the spellbook works meanwhile."}},
    {name = "Fight pack", title = "Thunder Clap", icon = "spell_nature_thunderclap", lo = 6, hi = 19,
     body = "#showtooltip Thunder Clap\n/startattack [harm,nodead]\n/cast Thunder Clap", pad = "RT+↑", kb = "5",
     tips = {"Clap when the pack reaches you: it hits up to four enemies and slows their attacks by 20%. Works in Battle and Defensive.", "Switch to anything it missed and Clap again for adds, threat or to keep the slow up.", "Costs 20 Rage, 14 with maxed Improved Thunder Clap at 17. From 20 Cleave rides along on this button."}},
    {name = "Fight pack", title = "Thunder Clap + Cleave", icon = "spell_nature_thunderclap", lo = 20, hi = 29,
