"ability_warrior_revenge", "spell_nature_enchantarmor", "ability_warrior_warcry"}}, {level = 16, spells = {"Shield Block", "Heroic Strike (Rank 3)", "Mocking Blow (Rank 1)"}, notes = {"Increases block chance for up to 2 blocks in 7 seconds. A block can light Revenge.", "Single-target Rage dump.", "Battle Stance only."}, icons = {"ability_defend", "ability_rogue_ambush", "ability_warrior_punishingblow"}}, {level = 18, spells = {"Thunder Clap (Rank 2)", "Disarm"}, notes = {"Multi-mob opener and attack-speed slow.", "Great vs. hard-hitting weapon users."}, icons = {"spell_nature_thunderclap", "ability_warrior_disarm"}}, {level = 20, spells = {"Victory Rush", "Cleave (Rank 1)", "Rend (Rank 3)", "Slam (Rank 1)", "Retaliation"}, notes = {"Use when lit within 20 seconds of a qualifying kill. Heals 10% on a hit and has a 30-second cooldown.", "Fight pack queues it after each Thunder Clap.", "Works in Defensive Stance and ignores armor. Use Rend again on enemies that will live through the bleed.", "Cast time; weak with a one-hander.", "Battle Stance only."}, icons = {"ability_warrior_devastate", "ability_warrior_cleave", "ability_gouge", "ability_warrior_decisivestrike", "ability_warrior_challange"}}, {level = 22, spells = {"Battle Shout (Rank 3)", "Sunder Armor (Rank 2)", "Intimidating Shout"}, notes = {"Keep it up always.", "Threat and filler.", "Emergency fear — careful near other mobs."}, icons = {"ability_warrior_battleshout", "ability_warrior_sunder", "ability_golemthunderclap"}}, {level = 24, spells = {"Revenge (Rank 2)", "Heroic Strike (Rank 4)", "Demoralizing Shout (Rank 2)", "Execute (Rank 1)"}, notes = {"Your main attack until Shield Slam.", "Single-target Rage dump.", "Less damage taken on packs. Your Battle Shout button casts it in combat.", "Needs Battle or Berserker Stance."}, icons = {"ability_warrior_revenge", "ability_rogue_ambush", "ability_warrior_warcry", "inv_sword_48"}}, {level = 26, spells = {"Charge (Rank 2)", "Challenging Shout", "Mocking Blow (Rank 2)"}, notes = {"Opener out of combat. Works in Defensive Stance with Vanguard.", "Group emergency taunt.", "Battle Stance only."}, icons = {"ability_warrior_charge", "ability_bullrush", "ability_warrior_punishingblow"}}, {level = 28, spells = {"Shield Wall", "Thunder Clap (Rank 3)", "Overpower (Rank 2)"}, notes = {"60% less damage for 12 sec.", "Multi-mob opener and attack-speed slow.", "Battle Stance only. Your Revenge button casts it there."}, icons = {"ability_warrior_shieldwall", "spell_nature_thunderclap", "ability_meleedamage"}}, {level = 30, spells = {"Cleave (Rank 2)", "Rend (Rank 4)", "Berserker Rage", "Berserker Stance", "Intercept (Rank 1)", "Slam (Rank 2)"}, notes = {"Fight pack queues it after each Thunder Clap.", "Works in Defensive Stance and ignores armor. Use Rend again on enemies that will live through the bleed.", "Fear break, but needs Berserker Stance.", "Not used as Protection.", "Berserker Stance only.", "Cast time; weak with a one-hander."}, icons = {"ability_warrior_cleave", "ability_gouge", "spell_nature_ancestralguardian", "ability_racial_avatar", "ability_rogue_sprint", "ability_warrior_decisivestrike"}}, {level = 32, spells = {"Shield Bash (Rank 2)", "Heroic Strike (Rank 5)", "Battle Shout (Rank 4)", "Hamstring (Rank 2)", "Execute (Rank 2)"}, notes = {"Interrupt casters.", "Single-target Rage dump.", "Keep it up always.", "For fleeing enemies. Battle Stance only — use the Hamstring macro.", "Needs Battle or Berserker Stance."}, icons = {"ability_warrior_shieldbash", "ability_rogue_ambush", "ability_warrior_battleshout", "ability_shockwave", "inv_sword_48"}}, {level = 34, spells = {"Revenge (Rank 3)", "Sunder Armor (Rank 3)", "Demoralizing Shout (Rank 3)"}, notes = {"Your main attack until Shield Slam.", "Threat and filler.", "Less damage taken on packs. Your Battle Shout button casts it in combat."}, icons = {"ability_warrior_revenge", "ability_warrior_sunder", "ability_warrior_warcry"}}, {level = 36, spells = {"Whirlwind", "Mocking Blow (Rank 3)"}, notes = {"Berserker Stance only.", "Battle Stance only."}, icons = {"ability_whirlwind", "ability_warrior_punishingblow"}}, {level = 38, spells = {"Thunder Clap (Rank 4)", "Pummel (Rank 1)", "Slam (Rank 3)"}, notes = {"Multi-mob opener and attack-speed slow.", "Berserker Stance only; use Shield Bash.", "Cast time; weak with a one-hander."}, icons = {"spell_nature_thunderclap", "inv_gauntlets_04", "ability_warrior_decisivestrike"}}, {level = 40, spells = {"Shield Slam (Rank 1)", "Heroic Strike (Rank 6)", "Cleave (Rank 3)", "Rend (Rank 5)", "Execute (Rank 3)"}, notes = {"From your talent point", "Single-target Rage dump.", "Fight pack queues it after each Thunder Clap.", "Works in Defensive Stance and ignores armor. Use Rend again on enemies that will live through the bleed.", "Needs Battle or Berserker Stance."}, icons = {"inv_shield_05", "ability_rogue_ambush", "ability_warrior_cleave", "ability_gouge", "inv_sword_48"}}, {level = 42, spells = {"Battle Shout (Rank 5)", "Intercept (Rank 2)"}, notes = {"Keep it up always.", "Berserker Stance only."}, icons = {"ability_warrior_battleshout", "ability_rogue_sprint"}}, {level = 44, spells = {"Revenge (Rank 4)", "Demoralizing Shout (Rank 4)", "Overpower (Rank 3)"}, notes = {"Your main attack until Shield Slam.", "Less damage taken on packs. Your Battle Shout button casts it in combat.", "Battle Stance only. Your Revenge button casts it there."}, icons = {"ability_warrior_revenge", "ability_warrior_warcry", "ability_meleedamage"}}, {level = 46, spells = {"Charge (Rank 3)", "Sunder Armor (Rank 4)", "Slam (Rank 4)", "Mocking Blow (Rank 4)"}, notes = {"Opener out of combat. Works in Defensive Stance with Vanguard.", "Threat and filler.", "Cast time; weak with a one-hander.", "Battle Stance only."}, icons = {"ability_warrior_charge", "ability_warrior_sunder", "ability_warrior_decisivestrike", "ability_warrior_punishingblow"}}, {level = 48, spells = {"Shield Slam (Rank 2)", "Thunder Clap (Rank 5)", "Heroic Strike (Rank 7)", "Execute (Rank 4)"}, notes = {"New rank of your best attack.", "Multi-mob opener and attack-speed slow.", "Single-target Rage dump.", "Needs Battle or Berserker Stance."}, icons = {"inv_shield_05", "spell_nature_thunderclap", "ability_rogue_ambush", "inv_sword_48"}}, {level = 50, spells = {"Cleave (Rank 4)", "Rend (Rank 6)", "Recklessness"}, notes = {"Fight pack queues it after each Thunder Clap.", "Works in Defensive Stance and ignores armor. Use Rend again on enemies that will live through the bleed.", "Berserker Stance only."}, icons = {"ability_warrior_cleave", "ability_gouge", "ability_criticalstrike"}}, {level = 52, spells = {"Shield Bash (Rank 3)", "Battle Shout (Rank 6)", "Intercept (Rank 3)"}, notes = {"Interrupt casters.", "Keep it up always.", "Berserker Stance only."}, icons = {"ability_warrior_shieldbash", "ability_warrior_battleshout", "ability_rogue_sprint"}}, {level = 54, spells = {"Shield Slam (Rank 3)", "Revenge (Rank 5)", "Demoralizing Shout (Rank 5)", "Hamstring (Rank 3)", "Slam (Rank 5)"}, notes = {"New rank of your best attack.", "Your main attack until Shield Slam.", "Less damage taken on packs. Your Battle Shout button casts it in combat.", "For fleeing enemies. Battle Stance only — use the Hamstring macro.", "Cast time; weak with a one-hander."}, icons = {"inv_shield_05", "ability_warrior_revenge", "ability_warrior_warcry", "ability_shockwave", "ability_warrior_decisivestrike"}}, {level = 56, spells = {"Heroic Strike (Rank 8)", "Execute (Rank 5)", "Mocking Blow (Rank 5)"}, notes = {"Single-target Rage dump.", "Needs Battle or Berserker Stance.", "Battle Stance only."}, icons = {"ability_rogue_ambush", "inv_sword_48", "ability_warrior_punishingblow"}}, {level = 58, spells = {"Thunder Clap (Rank 6)", "Sunder Armor (Rank 5)", "Pummel (Rank 2)"}, notes = {"Multi-mob opener and attack-speed slow.", "Threat and filler.", "Berserker Stance only; use Shield Bash."}, icons = {"spell_nature_thunderclap", "ability_warrior_sunder", "inv_gauntlets_04"}}, {level = 60, spells = {"Shield Slam (Rank 4)", "Revenge (Rank 6)", "Heroic Strike (Rank 9)", "Battle Shout (Rank 7)", "Cleave (Rank 5)", "Rend (Rank 7)", "Overpower (Rank 4)"}, notes = {"New rank of your best attack.", "Your main attack until Shield Slam.", "Single-target Rage dump.", "Keep it up always.", "Fight pack queues it after each Thunder Clap.", "Works in Defensive Stance and ignores armor. Use Rend again on enemies that will live through the bleed.", "Battle Stance only. Your Revenge button casts it there."}, icons = {"inv_shield_05", "ability_warrior_revenge", "ability_rogue_ambush", "ability_warrior_battleshout", "ability_warrior_cleave", "ability_gouge", "ability_meleedamage"}}}, br = {
    {level = 1, range = "Levels 1–9", title = "Before Talents", icon = "ability_warrior_battleshout",
     intro = "Start with auto-attacks. A one-handed weapon and shield set you up for Protection at level 10.",
     steps = {"Keep Battle Shout up when you have the Rage. Use Heroic Strike with spare Rage and let normal swings build it back.", "From 4, use Fight to Charge from Battle before combat. Use Rend separately on enemies that will live through enough ticks.", "From 6, use the dedicated Thunder Clap button when several enemies are in range. It costs 20 Rage at first.", "From 8, use Hamstring for runners in Battle Stance."},
     stepIcons = {"ability_warrior_battleshout", "ability_warrior_charge", "spell_nature_thunderclap", "ability_shockwave"}},
    {level = 10, range = "Levels 10–19", title = "Shield On", icon = "ability_racial_bloodrage",
     intro = "Complete your level-10 Defensive Stance quest and get Sunder Armor and Taunt. Tank in Defensive Stance with a shield.",
     steps = {"For Protection, Fight switches to Battle when needed, Charges on a separate press, then enters Defensive in combat. Tactical Mastery at 14 keeps up to 10 Rage.", "Fight uses Bloodrage in combat whenever it is ready, so you never press it yourself. Shout Battle Shout before the pull.", "Clap when the pack reaches you. Tab to enemies that need threat and use Revenge from 14 or Sunder as a filler. Save Rage for the next Clap if threat is stable.", "Taunt a loose enemy, or select the party member it is hitting and press Taunt: Sunder follows on the same press. Keep Shield Bash handy from 12 for a caster.", "From 16, Shield Block and Revenge ride on each other's buttons: press Block when melee hits are coming and Revenge when it lights up.", "Solo, Rend enemies that will live through the bleed. Use Sunder when the armor reduction will pay off."},
     stepIcons = {"ability_warrior_charge", "ability_racial_bloodrage", "spell_nature_thunderclap", "ability_warrior_shieldbash", "ability_defend", "ability_gouge"}},
    {level = 20, range = "Levels 20–29", title = "Pack Control", icon = "ability_warrior_devastate",
     intro = "Victory Rush helps you heal between kills, and Vanguard at 25 lets you Charge from Defensive Stance.",
     steps = {"Use Victory Rush when lit on the next enemy. Its heal is 10% and the attack has a 30-second cooldown.", "Tank packs with Thunder Clap and spread threat with Revenge and Sunder. Clap hits up to four enemies, so watch mobs it missed.", "In combat your Battle Shout button casts Demoralizing Shout. Fight pack queues Cleave after every Clap that lands.", "From 25, Fight can Charge out of combat from Defensive with Vanguard. Without the talent, it still uses Battle to Charge.", "Last Stand and Shield Wall are separate cooldowns from 26 and 28. Challenging Shout at 26 buys time to build threat on a loose pack.", "As group DPS, assist the tank, keep Battle Shout up and use Battle or Berserker once unlocked. Use your DPS buttons to stay in that stance. Use Execute from 24 in either of those stances when the target is at 20% or less."},
     stepIcons = {"ability_warrior_devastate", "spell_nature_thunderclap", "ability_warrior_cleave", "ability_warrior_shieldcharge", "ability_bullrush", "inv_sword_48"}},
    {level = 30, range = "Levels 30–39", title = "Cheaper, Harder Hits", icon = "ability_thunderbolt",
     intro = "Concussion Blow handles susceptible casters and runners. Focused Rage saves Rage on attacks and Bastion increases damage with a shield.",
     steps = {"Take Revenge when it lights up. From 33 on this plan, it costs 2 Rage and Thunder Clap costs 11.", "After the first Clap, use single-target threat where it is needed. Save Rage for adds, the next pull or Shield Bash.", "Use Shield Block for incoming melee and the Shout button in combat for Demoralizing Shout.", "Use Concussion Blow from the spellbook for a stun. From 38 the Shield Bash bind also uses Pummel in Berserker once trained."},
     stepIcons = {"ability_warrior_revenge", "spell_nature_thunderclap", "ability_defend", "ability_thunderbolt"}},
    {level = 40, range = "Levels 40–60", title = "Shield Slam", icon = "inv_shield_05",
     intro = "Spend the Shield Slam talent point and equip a shield. Shield Block Value adds to Slam damage. Train new ranks at 48, 54 and 60.",
     steps = {"Single target: Slam when ready, use Revenge when lit and fill with Sunder when you need threat or armor reduction.", "Packs: Clap in Defensive as enemies reach you, then tab through enemies that need threat. Use Slam on the kill target or a mob you might lose. A cheap Revenge can cover a second mob.", "Clap again for adds, a threat gap or a slow refresh. Use Sunder for threat when Slam and Revenge are unavailable. Build and maintain stacks on durable targets when assigned.", "Fight pack queues Cleave with each Clap. When Rage is short and threat is stable, skip the Clap and pool Rage for the next pull.", "Shield Slam and Revenge keep Shield Block rolling. Shield Wall has its own bind and is on a four-minute cooldown from 41 on this plan."},
     stepIcons = {"inv_shield_05", "spell_nature_thunderclap", "ability_warrior_sunder", "ability_warrior_cleave", "ability_warrior_shieldwall"}},
  }, spec = "Protection", guide = "Prot Warrior"},
  MAGE = {macros = {{name = "Nuke", title = "Nuke", icon = "spell_frost_frostbolt02", lo = 1, hi = 60, body = "#showtooltip\n/cast Frostbolt\n/cast Fireball", pad = "RT+A", kb = "1", tips = {"Every press: Frostbolt. Before you learn it at 4, Fireball."}}, {name = "Finisher Shatter", title = "Finisher / Shatter", icon = "spell_frost_frostblast", lo = 6, hi = 60, body = "#showtooltip\n/cast Ice Lance\n/cast Fire Blast", pad = "RT+B", kb = "2", tips = {"Levels 6–19: Fire Blast — instant finisher.", "From 20: Ice Lance — press it right after Frost Nova, a Frostbite freeze or a Fingers of Frost proc. It shares Fire Blast's 8 sec cooldown, so Fire Blast no longer fires from here."}}, {name = "Get away", title = "Get away", icon = "spell_frost_frostnova", lo = 10, hi = 19, body = "#showtooltip\n/cast Frost Nova", pad = "LT+A", kb = "Q", tips = {"One press: Frost Nova — roots everything around you.", "Blink joins this button at 20."}}, {name = "Get away", title = "Get away", icon = "spell_frost_frostnova", lo = 20, hi = 60, body = "#showtooltip\n/castsequence reset=combat Frost Nova, Blink", pad = "LT+A", kb = "Q", tips = {"First press: Frost Nova — roots everything around you.", "Second press: Blink 20 yards away.", "Resets: Every new fight starts on Frost Nova. If Nova is still cooling down (25 sec, 21 with Improved Frost Nova) the macro waits on it — use your separate Blink button instead."}}, {name = "Pack", title = "Pack", icon = "spell_frost_glacier", lo = 26, hi = 60, body = "#showtooltip\n/castsequence reset=combat Frost Nova, Cone of Cold, Arcane Explosion, Arcane Explosion, Arcane Explosion", pad = "RT+X", kb = "3", tips = {"Each press: Frost Nova → Cone of Cold → Arcane Explosion ×3.", "If it says \"not ready\": Nova is still on cooldown — use your Arcane Explosion key instead."}}, {name = "Mana gem", title = "Mana gem", icon = "inv_misc_gem_ruby_01", lo = 28, hi = 60, body = "#showtooltip\n/use Mana Ruby\n/use Mana Citrine\n/use Mana Jade\n/use Mana Agate", pad = "LT+X", kb = "R", tips = {"One press: Uses whichever mana gem you carry. Evocation stays on its own key."}}, {name = "Shield up", title = "Shield up", icon = "spell_shadow_detectlesserinvisibility", lo = 20, hi = 60, body = "#showtooltip\n/cast Ice Barrier\n/cast Mana Shield", pad = "LT+B", kb = "E", tips = {"Levels 20–39: Mana Shield.", "From 40: Ice Barrier — press it before every pull and whenever it's ready. Mana Shield moves to its own key."}}, {name = "Armor", title = "Armor", icon = "spell_frost_frostarmor02", lo = 1, hi = 60, body = "#showtooltip\n/cast Ice Armor\n/cast Frost Armor", pad = "LT+↑", kb = "Shift+1", tips = {"One press: Ice Armor once you have it (30+), otherwise Frost Armor."}}}, plan = {{name = "Improved Frostbolt", tree = "Frost", from = 10, to = 14, why = "Frostbolt is the spell you cast most. Shaving half a second off it is the single biggest speed-up to every kill from 10 to 60.", more = "Another 0.1 sec off Frostbolt.", max = 5, icon = "spell_frost_frostbolt02"}, {name = "Precision", tree = "Frost", from = 15, to = 16, why = "Missed spells waste mana and let mobs reach you. Forever merged Arcane Focus into Precision, so each point is now +2% hit with every school — two points nearly stop at-level misses.", more = "+2% more spell hit.", max = 3, icon = "spell_ice_magicdamage"}, {name = "Frostbite", tree = "Frost", from = 17, to = 19, why = "Every Frostbolt chill now has a chance to freeze the target solid — free roots, and later, free Shatter crits.", more = "+5% more freeze chance per chill.", max = 3, icon = "spell_frost_frostarmor"}, {name = "Ice Lance", tree = "Frost", from = 20, to = 20, why = "The earliest it opens (row 3 needs 10 points). Instant, hits frozen targets for 300% more, on an 8 sec cooldown it shares with Fire Blast — so it replaces Fire Blast as your finisher. Nova or Frostbite a mob, then Lance it.", more = "", max = 1, icon = "spell_frost_frostblast"}, {name = "Ice Shards", tree = "Frost", from = 21, to = 25, why = "+100% Frost crit bonus: crits hit for 2× instead of 1.5×. Pays off hugely once Shatter adds 50% crit against frozen targets.", more = "+20% more Frost crit bonus.", max = 5, icon = "spell_frost_iceshard"}, {name = "Shatter", tree = "Frost", from = 26, to = 28, why = "The heart of Frost: +50% crit chance against frozen targets, and in Forever it no longer needs Improved Frost Nova first. Nova → Ice Lance → Frostbolt now crits more often than not.", more = "More crit chance against frozen targets.", max = 3, icon = "spell_frost_frostshock"}, {name = "Ice Block", tree = "Frost", from = 29, to = 29, why = "Ten seconds of immunity on a 5 minute cooldown — your get-out-of-death card on bad pulls.", more = "", max = 1, icon = "spell_frost_frost"}, {name = "Fingers of Frost", tree = "Frost", from = 30, to = 31, why = "Every chill (Frostbolt, Cone of Cold, Blizzard with Improved Blizzard) has a 15% chance to make your next two spells within 15 sec treat the target as frozen. Every proc is a free Shatter combo — no Nova needed.", more = "Two empowered spells per proc instead of one.", max = 2, icon = "ability_mage_wintersgrasp"}, {name = "Improved Frost Nova", tree = "Frost", from = 32, to = 33, why = "Frost Nova every 21 sec instead of 25 — more freezes, more Shatters, more safety.", more = "Frost Nova 2 more sec faster.", max = 2, icon = "spell_frost_freezingbreath"}, {name = "Cold Snap", tree = "Frost", from = 34, to = 34, why = "Finishes the cooldown on all your other Frost spells — a second Nova, Ice Block or Cone of Cold on a bad pull — and it is the required prerequisite for Ice Barrier at 40.", more = "", max = 1, icon = "spell_frost_wizardmark"}, {name = "Frost Channeling", tree = "Frost", from = 35, to = 37, why = "Mana is the real limit on how fast a Mage levels. 15% cheaper Frost spells means more pulls between drinks.", more = "5% more off every Frost spell.", max = 3, icon = "spell_frost_stun"}, {name = "Arctic Reach", tree = "Frost", from = 38, to = 39, why = "+20% range: pull from further away and get more Frostbolts in before anything reaches you.", more = "+10% more range and radius.", max = 2, icon = "spell_shadow_darkritual"}, {name = "Ice Barrier", tree = "Frost", from = 40, to = 40, why = "The capstone and your best leveling tool, open the moment you hit 40: an absorb shield every 30 sec that adds 15% Frost damage for a minute (20% while it holds) and stops hits from pushing back your casts. Keep it up always.", more = "", max = 1, icon = "spell_ice_lament"}, {name = "Permafrost", tree = "Frost", from = 41, to = 43, why = "Longer, stronger slows mean more Frostbolts before melee mobs arrive — and more time for Frostbite and Fingers of Frost to proc.", more = "Chills last longer again.", max = 3, icon = "spell_frost_wisp"}, {name = "Precision", tree = "Frost", from = 44, to = 44, why = "Higher-level mobs resist more. The third point brings Precision to 6% hit.", more = "", max = 3, icon = "spell_ice_magicdamage"}, {name = "Improved Cone of Cold", tree = "Frost", from = 45, to = 47, why = "Cone of Cold is your burst on packs. 35% more damage turns AoE pulls from risky to fast.", more = "More Cone of Cold damage.", max = 3, icon = "spell_frost_glacier"}, {name = "Improved Blizzard", tree = "Frost", from = 48, to = 50, why = "Blizzard now chills (40% slow at 3/3), and chills can trigger Frostbite freezes and Fingers of Frost. Train every Blizzard rank: Forever cuts those procs on a rank learned more than 12 levels ago.", more = "Stronger Blizzard slow.", max = 3, icon = "spell_frost_icestorm"}, {name = "Frost Warding", tree = "Frost", from = 51, to = 52, why = "Ice Barrier and Frost Ward absorb 20% more, Ice Armor gets 30% stronger, and Frost Ward can now fully negate a spell. Pure survivability.", more = "Barrier absorbs another 10%.", max = 2, icon = "spell_frost_frostward"}, {name = "Incineration", tree = "Fire", from = 53, to = 57, why = "Every Frost talent worth having is done. Incineration (Fire row 1, now 5 points for +10%) adds crit to Ice Lance and Fire Blast even when the target isn’t frozen.", more = "+2% more Ice Lance crit.", max = 5, icon = "spell_fire_flameshock"}, {name = "Winter's Chill", tree = "Frost", from = 58, to = 60, why = "Last points: each Frostbolt can stack +20% damage onto your next Cone of Cold (Blizzard, 2 Nov) for the opening burst on packs.", more = "+20% more chance to stack.", max = 5, icon = "spell_frost_chillingblast"}}, train = {{level = 1, spells = {"Fireball (Rank 1)", "Arcane Intellect (Rank 1)", "Frost Armor (Rank 1)"}, notes = {"Your only attack until 4.", "Keep it up — more mana.", "Armor and slows attackers. Replaced by Ice Armor at 30."}, icons = {"spell_fire_flamebolt", "spell_holy_magicalsentry", "spell_frost_frostarmor02"}}, {level = 4, spells = {"Frostbolt (Rank 1)", "Conjure Water (Rank 1)"}, notes = {"Your main nuke. Always train new ranks.", "Free drinks — saves a lot of gold."}, icons = {"spell_frost_frostbolt02", "inv_drink_06"}}, {level = 6, spells = {"Fire Blast (Rank 1)", "Conjure Food (Rank 1)", "Fireball (Rank 2)", "Comprehend Scroll"}, notes = {"Instant finisher.", "Free food.", "Frostbolt replaces it at 4.", "New in Forever. Utility only — not needed for leveling."}, icons = {"spell_fire_fireball", "inv_misc_food_10", "spell_fire_flamebolt", "inv_misc_note_01"}}, {level = 8, spells = {"Frostbolt (Rank 2)", "Polymorph (Rank 1)", "Arcane Missiles (Rank 1)"}, notes = {"Your main nuke. Always train new ranks.", "Sheep the extra mob.", "Mana-heavy without Arcane talents."}, icons = {"spell_frost_frostbolt02", "spell_nature_polymorph", "spell_nature_starfall"}}, {level = 10, spells = {"Frost Nova (Rank 1)", "Frost Armor (Rank 2)", "Conjure Water (Rank 2)"}, notes = {"Root, then Shatter. Your core defensive.", "Armor and slows attackers. Replaced by Ice Armor at 30.", "Free drinks — saves a lot of gold."}, icons = {"spell_frost_frostnova", "spell_frost_frostarmor02", "inv_drink_06"}}, {level = 12, spells = {"Conjure Food (Rank 2)", "Slow Fall", "Dampen Magic (Rank 1)", "Fireball (Rank 3)"}, notes = {"Free food.", "Utility.", "Situational vs. casters.", "Frostbolt replaces it at 4."}, icons = {"inv_misc_food_10", "spell_magic_featherfall", "spell_nature_abolishmagic", "spell_fire_flamebolt"}}, {level = 14, spells = {"Frostbolt (Rank 3)", "Arcane Intellect (Rank 2)", "Arcane Explosion (Rank 1)", "Fire Blast (Rank 2)"}, notes = {"Your main nuke. Always train new ranks.", "Keep it up — more mana.", "Instant AoE on nova'd packs.", "Instant finisher until Ice Lance."}, icons = {"spell_frost_frostbolt02", "spell_holy_magicalsentry", "spell_nature_wispsplode", "spell_fire_fireball"}}, {level = 16, spells = {"Arcane Missiles (Rank 2)", "Flamestrike (Rank 1)"}, notes = {"Mana-heavy without Arcane talents.", "Blizzard does this better for Frost."}, icons = {"spell_nature_starfall", "spell_fire_selfdestruct"}}, {level = 18, spells = {"Remove Lesser Curse", "Amplify Magic (Rank 1)", "Fireball (Rank 4)"}, notes = {"Groups and nasty curses.", "Rarely useful.", "Frostbolt replaces it at 4."}, icons = {"spell_nature_removecurse", "spell_holy_flashheal", "spell_fire_flamebolt"}}, {level = 20, spells = {"Frostbolt (Rank 4)", "Ice Lance (Rank 1)", "Blink", "Blizzard (Rank 1)", "Evocation", "Frost Armor (Rank 3)", "Mana Shield (Rank 1)", "Conjure Water (Rank 3)", "Polymorph (Rank 2)", "Teleports", "Fire Ward (Rank 1)"}, notes = {"Your main nuke. Always train new ranks.", "From your talent point.", "Escape and gap — also breaks stuns and roots.", "Your main pack-killer.", "Refills mana — use before you sit to drink.", "Armor and slows attackers. Replaced by Ice Armor at 30.", "Emergency absorb before Ice Barrier.", "Free drinks — saves a lot of gold.", "Sheep the extra mob.", "Ironforge / Stormwind or Orgrimmar / Undercity.", "Vs. fire casters."}, icons = {"spell_frost_frostbolt02", "spell_frost_frostblast", "spell_arcane_blink", "spell_frost_icestorm", "spell_nature_purge", "spell_frost_frostarmor02", "spe