5.", "New: instant strike, 10 sec cooldown.", "Undead and Demons only, 15 sec cooldown.", "Swap in if mana is tight.", "Situational."}, icons = {"ability_thunderclap", "classicon_paladin", "spell_holy_excorcism_02", "spell_holy_sealofwisdom", "spell_frost_wizardmark"}}, {level = 46, spells = {"Retribution Aura (Rank 4)", "Holy Light (Rank 7)", "Blessing of Sacrifice (Rank 1)"}, notes = {"Damages attackers — great on packs.", "Slow, big heal between fights.", "Group."}, icons = {"spell_holy_auraoflight", "spell_holy_holybolt", "spell_holy_sealofsacrifice"}}, {level = 48, spells = {"Redemption (Rank 4)", "Seal of Wisdom (Rank 2)", "Fire Resistance Aura (Rank 2)"}, notes = {"Resurrect.", "Mana seal.", "Situational."}, icons = {"spell_holy_resurrection", "spell_holy_righteousnessaura", "spell_fire_sealoffire"}}, {level = 50, spells = {"Seal of Command (Rank 4)", "Consecration (Rank 4)", "Divine Shield (Rank 2)", "Flash of Light (Rank 5)", "Holy Wrath (Rank 1)", "Lay on Hands (Rank 3)", "Devotion Aura (Rank 6)", "Seal of Righteousness (Rank 7)", "Seal of Light (Rank 3)", "Seal of Fury (Rank 6)"}, notes = {"New rank of your main seal.", "Trainable in Forever — AoE.", "12 sec immunity, but you deal 50% less damage. Shares a 5 min cooldown with Divine Protection.", "Fast heal.", "Undead/Demon AoE.", "Full heal, 20 min cooldown.", "Armor aura.", "Backup seal; from 40 your Unsealed Wrath swap.", "Self-heal seal.", "Tank seal."}, icons = {"ability_warrior_innerrage", "spell_holy_innerfire", "spell_holy_divineintervention", "spell_holy_flashheal", "spell_holy_excorcism", "spell_holy_layonhands", "spell_holy_devotionaura", "ability_thunderbolt", "spell_holy_healingaura", "spell_holy_retributionaura"}}, {level = 52, spells = {"Holy Strike (Rank 7)", "Hammer of Wrath (Rank 2)", "Blessing of Might (Rank 6)", "Exorcism (Rank 5)", "Greater Blessing of Might (Rank 1)", "Turn Undead (Rank 3)", "Shadow Resistance Aura (Rank 3)", "Seal of the Crusader (Rank 6)"}, notes = {"New: instant strike, 10 sec cooldown.", "Execute below 20% health, 6 sec cooldown. Instant with Champion of the Light 5/5.", "Attack Power — lasts an hour.", "Undead and Demons only, 15 sec cooldown.", "Group buff.", "Undead CC.", "Situational.", "Weak for leveling."}, icons = {"classicon_paladin", "ability_thunderclap", "spell_holy_fistofjustice", "spell_holy_excorcism_02", "spell_holy_greaterblessingofkings", "spell_holy_turnundead", "spell_shadow_sealofkings", "spell_holy_holysmite"}}, {level = 54, spells = {"Hammer of Justice (Rank 4)", "Holy Light (Rank 8)", "Blessing of Wisdom (Rank 5)", "Greater Blessing of Wisdom (Rank 1)", "Blessing of Sacrifice (Rank 2)"}, notes = {"Stun — stops casters and runners.", "Slow, big heal between fights.", "Swap in if mana is tight.", "Group buff.", "Group."}, icons = {"spell_holy_sealofmight", "spell_holy_holybolt", "spell_holy_sealofwisdom", "spell_holy_greaterblessingofwisdom", "spell_holy_sealofsacrifice"}}, {level = 56, spells = {"Retribution Aura (Rank 5)", "Frost Resistance Aura (Rank 3)"}, notes = {"Damages attackers — great on packs.", "Situational."}, icons = {"spell_holy_auraoflight", "spell_frost_wizardmark"}}, {level = 58, spells = {"Flash of Light (Rank 6)", "Seal of Righteousness (Rank 8)", "Seal of Wisdom (Rank 3)", "Seal of Fury (Rank 7)"}, notes = {"Fast heal.", "Backup seal; from 40 your Unsealed Wrath swap.", "Mana seal.", "Tank seal."}, icons = {"spell_holy_flashheal", "ability_thunderbolt", "spell_holy_righteousnessaura", "spell_holy_retributionaura"}}, {level = 60, spells = {"Seal of Command (Rank 5)", "Holy Strike (Rank 8)", "Consecration (Rank 5)", "Hammer of Wrath (Rank 3)", "Blessing of Might (Rank 7)", "Holy Light (Rank 9)", "Exorcism (Rank 6)", "Devotion Aura (Rank 7)", "Holy Wrath (Rank 2)", "Redemption (Rank 5)", "Blessing of Wisdom (Rank 6)", "Seal of Light (Rank 4)", "Greater Blessing of Might (Rank 2)", "Greater Blessing of Wisdom (Rank 2)", "Greater Blessing of Kings", "Fire Resistance Aura (Rank 3)"}, notes = {"New rank of your main seal.", "New: instant strike, 10 sec cooldown.", "Trainable in Forever — AoE.", "Execute below 20% health, 6 sec cooldown. Instant with Champion of the Light 5/5.", "Attack Power — lasts an hour.", "Slow, big heal between fights.", "Undead and Demons only, 15 sec cooldown.", "Armor aura.", "Undead/Demon AoE.", "Resurrect.", "Swap in if mana is tight.", "Self-heal seal.", "Group buff.", "Group buff.", "Group buff — costs a Symbol of Kings.", "Situational."}, icons = {"ability_warrior_innerrage", "classicon_paladin", "spell_holy_innerfire", "ability_thunderclap", "spell_holy_fistofjustice", "spell_holy_holybolt", "spell_holy_excorcism_02", "spell_holy_devotionaura", "spell_holy_excorcism", "spell_holy_resurrection", "spell_holy_sealofwisdom", "spell_holy_healingaura", "spell_holy_greaterblessingofkings", "spell_holy_greaterblessingofwisdom", "spell_magic_greaterblessingofkings", "spell_fire_sealoffire"}}}, br = {{level = 1, icon = "ability_thunderbolt", title = "Before Talents", range = "Levels 1–9", intro = "Seal, Judge, swing. Grab the biggest two-handed weapon you can — Paladin damage scales with slow, heavy hits.", steps = {"Seal of Righteousness on before every fight.", "Blessing of Might (4) and Devotion Aura on.", "Judgement (4) once you're in range — in Forever it no longer eats your seal.", "Holy Strike (6) every 10 sec.", "Holy Light yourself between fights instead of eating."}, stepIcons = {"ability_thunderbolt", "spell_holy_fistofjustice", "spell_holy_righteousfury", "classicon_paladin", "spell_holy_holybolt"}}, {level = 10, icon = "spell_holy_auraoflight", title = "Seal, Judge, Strike", range = "Levels 10–19", intro = "Benediction makes all of this cheaper. Retribution Aura (16) hurts everything that hits you.", steps = {"Retribution Aura from 16.", "Seal → Judgement → Holy Strike, then swing. Re-seal when it fades.", "Hammer of Justice to stop a caster or runner.", "Running dry? Swap Might for Blessing of Wisdom (14).", "Controller: the Fight macro on RT+A casts seal, Judgement and Holy Strike in order."}, stepIcons = {"spell_holy_auraoflight", "spell_holy_righteousfury", "spell_holy_sealofmight", "spell_holy_sealofwisdom", "inv_misc_note_01"}}, {level = 20, icon = "ability_warrior_innerrage", title = "Seal of Command", range = "Levels 20–29", intro = "Seal of Command (20) is your leveling seal for the rest of the game. Consecration and Blessing of Kings are trainable at 20 in Forever.", steps = {"Swap to the 20–60 Fight macro: Seal of Command, then Judgement and Holy Strike.", "Stun first with Hammer of Justice, then Judge Command (RT+Y) for double damage.", "Consecration (20) on 2+ mobs.", "Flash of Light (20) for quick top-ups.", "Pursuit of Justice (21–22): 15% faster everywhere."}, stepIcons = {"ability_warrior_innerrage", "spell_holy_sealofmight", "spell_holy_innerfire", "spell_holy_flashheal", "spell_holy_persuitofjustice"}}, {level = 30, icon = "spell_holy_prayerofhealing", title = "Vengeance", range = "Levels 30–39", intro = "Vengeance stacks damage after every crit. Repentance (33) handles a Humanoid add.", steps = {"Repentance an add (6 sec, damage breaks it) while you open on the first mob.", "Divine Shield (34) when a pull goes wrong — it halves your damage, so heal up inside it. Swap to the 34–60 Panic macro.", "Exorcism on Undead and Demons."}, stepIcons = {"spell_holy_prayerofhealing", "spell_holy_divineintervention", "spell_holy_excorcism_02"}}, {level = 40, icon = "spell_holy_blessedresillience", title = "Unsealed Wrath", range = "Levels 40–60", intro = "Your hits store copies of your seal for 15 sec (up to 3). Your next hit with a different seal releases them, each with its normal proc chance. Hammer of Wrath (44) finishes mobs under 20%.", steps = {"Fight with Command for three swings, then cast Righteousness (RT+←) — the next hit releases the stored Command copies.", "Hammer of Wrath below 20% health.", "Consecration + Holy Strike on packs."}, stepIcons = {"spell_holy_blessedresillience", "ability_thunderclap", "spell_holy_innerfire"}}}, spec = "Retribution", guide = "Retribution Paladin"},
  PRIEST = {macros = {{name = "Fight", title = "Fight", icon = "spell_shadow_unholyfrenzy", lo = 10, hi = 19, body = "#showtooltip\n/castsequence reset=target Mind Blast, Shadow Word: Pain, Shoot", pad = "RT+A", kb = "1", tips = {"Each press: Mind Blast → Shadow Word: Pain → wand. Then let the wand work.", "Cooldown: Mind Blast has an 8 sec cooldown. If it is still cooling from the last mob the press waits — use Pain on RT+Y meanwhile."}}, {name = "Fight", title = "Fight", icon = "spell_shadow_siphonmana", lo = 20, hi = 60, body = "#showtooltip\n/castsequence [nochanneling] reset=target Shadow Word: Pain, Mind Flay, Mind Flay, Mind Flay, Mind Flay, Mind Flay, Mind Flay, Mind Flay", pad = "RT+A", kb = "1", tips = {"First: Open with Mind Blast on RT+X from range.", "Each press: Pain, then Mind Flay ×7 (about 22 sec), then Pain again just before its 24 sec run out. No cooldowns inside, so it never stalls.", "Cooldowns: Mind Blast (RT+X) and Devouring Plague (RT+←) have their own buttons — press them when they light up.", "Range: Mind Flay reaches 20 yd (24 with Shadow Reach); out of range the press waits.", "Channeling: [nochanneling] stops a press cutting Mind Flay short."}}, {name = "Shield", title = "Shield", icon = "spell_holy_powerwordshield", lo = 6, hi = 60, body = "#showtooltip\n/cast [@player] Power Word: Shield", pad = "LT+A", kb = "Q", tips = {"One press: Shields you even with an enemy targeted.", "Not ready: 4 sec cooldown, and Weakened Soul blocks a new shield for 15 sec — then the press shows \"You can't do that yet\"."}}, {name = "Heal up", title = "Heal up", icon = "spell_holy_flashheal", lo = 1, hi = 60, body = "#showtooltip\n/cast [@player] Flash Heal\n/cast [@player] Lesser Heal", pad = "LT+B", kb = "E", tips = {"One press: Flash Heal from 20, Lesser Heal before. Not in Shadowform."}}, {name = "Finish", title = "Finish", icon = "spell_shadow_demonicfortitude", lo = 32, hi = 60, body = "#showtooltip\n/cast Shadow Word: Death", pad = "RT+B", kb = "2", tips = {"When: Only when the mob will die from it — otherwise 30% health backlash. 18 sec cooldown."}}}, plan = {{name = "Spirit Tap", tree = "Shadow", from = 10, to = 14, why = "The leveling talent: +20% chance per rank that a kill doubles your Spirit for 15 sec and keeps 50% of mana regen going while casting. 100% at 5/5 (non-trivial kills).", more = "+20% more chance.", max = 5, icon = "spell_shadow_requiem"}, {name = "Improved Shadow Word: Pain", tree = "Shadow", from = 15, to = 16, why = "Earliest row 2 opens. Shadow Word: Pain lasts 24 sec instead of 18 at 2/2 — one cast covers the whole fight.", more = "", max = 2, icon = "spell_shadow_shadowwordpain"}, {name = "Shadow Reach", tree = "Shadow", from = 17, to = 18, why = "+10% range per rank on offensive Shadow spells. At 2/2 Mind Blast and Pain reach 36 yd, Mind Flay 24 yd.", more = "", max = 2, icon = "spell_shadow_chilltouch"}, {name = "Shadow Focus", tree = "Shadow", from = 19, to = 19, why = "+1% Shadow hit — and the 10th point, which opens Mind Flay at 20.", more = "", max = 5, icon = "spell_shadow_burningspirit"}, {name = "Mind Flay", tree = "Shadow", from = 20, to = 20, why = "Earliest it opens (row 3, 10 points). Your filler: 45 mana, 63 Shadow damage over 3 sec and a 50% slow. 20 yd range (24 with Shadow Reach).", more = "", max = 1, icon = "spell_shadow_siphonmana"}, {name = "Improved Mind Flay", tree = "Shadow", from = 21, to = 22, why = "Each Mind Flay tick deals 10% more than the last per rank (20% at 2/2) — let it channel fully.", more = "", max = 2, icon = "spell_shadow_soulleech_2"}, {name = "Shadow Focus", tree = "Shadow", from = 23, to = 24, why = "Shadow Focus to 3/5: +3% Shadow hit, fewer resisted Mind Blasts. Brings you to 15 points for row 4.", more = "", max = 5, icon = "spell_shadow_burningspirit"}, {name = "Vampiric Embrace", tree = "Shadow", from = 25, to = 25, why = "Earliest it opens (row 4, 15 points). 40 mana, 30 sec cooldown: heals you for 20% of your Shadow damage for 30 sec. Required for Shadowform.", more = "", max = 1, icon = "spell_shadow_unsummonbuilding"}, {name = "Shadow Weaving", tree = "Shadow", from = 26, to = 28, why = "At 3/3 every Shadow spell adds +2% Shadow damage taken from you, 5 stacks (+10%) for 15 sec.", more = "", max = 3, icon = "spell_shadow_blackplague"}, {name = "Shadow Focus", tree = "Shadow", from = 29, to = 29, why = "Shadow Focus 4/5 (+4% hit) — the 20th point, which opens row 5 at 30.", more = "", max = 5, icon = "spell_shadow_burningspirit"}, {name = "Devouring Contagion", tree = "Shadow", from = 30, to = 31, why = "Earliest it opens (row 5, 20 points). At 2/2 Devouring Plague costs 50% less, and a target that dies with it spreads it to 2 enemies within 10 yd.", more = "", max = 2, icon = "spell_shadow_devouringplague"}, {name = "Silence", tree = "Shadow", from = 32, to = 32, why = "Silence a caster: 5 sec silence plus a 3 sec interrupt, 45 sec cooldown.", more = "", max = 1, icon = "spell_shadow_impphaseshift"}, {name = "Improved Mind Blast", tree = "Shadow", from = 33, to = 34, why = "Mind Blast cooldown 8 → 7 sec at 2/5. Also the 25th point, which opens row 6 at 35.", more = "", max = 5, icon = "spell_shadow_unholyfrenzy"}, {name = "Darkness", tree = "Shadow", from = 35, to = 39, why = "Earliest it opens (row 6, 25 points). +2% Shadow damage per rank, +10% at 5/5.", more = "+2% more.", max = 5, icon = "spell_shadow_twilight"}, {name = "Shadowform", tree = "Shadow", from = 40, to = 40, why = "Earliest it opens (row 7, 30 points + Vampiric Embrace). Shadow spells cost 50% less, +10% Shadow damage, +100% Shadow crit bonus, 15% less physical damage taken. No healing spells in it.", more = "", max = 1, icon = "spell_shadow_shadowform"}, {name = "Early Demise", tree = "Shadow", from = 41, to = 42, why = "+15% Shadow Word: Death crit per rank (+30% at 2/2) on targets at or below 20% health — exactly when you use it.", more = "", max = 2, icon = "spell_shadow_demonicfortitude"}, {name = "Shadow Focus", tree = "Shadow", from = 43, to = 43, why = "Shadow Focus 5/5: +5% Shadow hit.", more = "", max = 5, icon = "spell_shadow_burningspirit"}, {name = "Improved Mind Blast", tree = "Shadow", from = 44, to = 46, why = "Improved Mind Blast to 5/5: Mind Blast cooldown 8 → 5.5 sec.", more = "-0.5 sec more.", max = 5, icon = "spell_shadow_unholyfrenzy"}, {name = "Twin Disciplines", tree = "Discipline", from = 47, to = 51, why = "Shadow's damage talents are done. Instant spells (Pain, Devouring Plague, Death) deal +1% per rank, +5% at 5/5.", more = "+1% more.", max = 5, icon = "spell_holy_sealofvengeance"}, {name = "Mental Strength", tree = "Discipline", from = 52, to = 56, why = "Earliest row 2 opens in Discipline. +2% total Intellect per rank (+10%): a bigger mana pool.", more = "+2% more.", max = 5, icon = "spell_nature_enchantarmor"}, {name = "Inner Focus", tree = "Discipline", from = 57, to = 57, why = "Earliest it opens (row 3, 10 Discipline points). 3 min cooldown: next spell free with +25% crit — pair with Mind Blast or Death.", more = "", max = 1, icon = "spell_frost_windwalkon"}, {name = "Meditation", tree = "Discipline", from = 58, to = 60, why = "17/33/50% of mana regen keeps going while casting.", more = "", max = 3, icon = "spell_nature_sleep"}}, train = {{level = 1, spells = {"Smite", "Lesser Heal", "Power Word: Fortitude"}, notes = {"Early damage spell.", "Early heal.", "Stamina buff."}, icons = {"spell_holy_holysmite", "spell_holy_lesserheal", "spell_holy_wordfortitude"}}, {level = 4, spells = {"Shadow Word: Pain", "Train the new ranks of Shadow Word: Pain, Mind Blast, Mind Flay (28+), Devouring Plague (28+), Shadow Word: Death (40+), Power Word: Shield and your heals every visit."}, notes = {"Your core DoT.", "Train the new ranks of Shadow Word: Pain, Mind Blast, Mind Flay (28+), Devouring Plague (28+), Shadow Word: Death (40+), Power Word: Shield and your heals every visit."}, icons = {"spell_shadow_shadowwordpain", "inv_misc_book_09"}}, {level = 6, spells = {"Power Wo