nd Flay (28+), Devouring Plague (28+), Shadow Word: Death (40+), Power Word: Shield and your heals every visit."}, notes = {"Train the new ranks of Shadow Word: Pain, Mind Blast, Mind Flay (28+), Devouring Plague (28+), Shadow Word: Death (40+), Power Word: Shield and your heals every visit."}, icons = {"inv_misc_book_09"}}, {level = 56, spells = {"Prayer of Shadow Protection", "Train the new ranks of Shadow Word: Pain, Mind Blast, Mind Flay (28+), Devouring Plague (28+), Shadow Word: Death (40+), Power Word: Shield and your heals every visit."}, notes = {"Group buff.", "Train the new ranks of Shadow Word: Pain, Mind Blast, Mind Flay (28+), Devouring Plague (28+), Shadow Word: Death (40+), Power Word: Shield and your heals every visit."}, icons = {"spell_holy_prayerofshadowprotection", "inv_misc_book_09"}}, {level = 58, spells = {"Train the new ranks of Shadow Word: Pain, Mind Blast, Mind Flay (28+), Devouring Plague (28+), Shadow Word: Death (40+), Power Word: Shield and your heals every visit."}, notes = {"Train the new ranks of Shadow Word: Pain, Mind Blast, Mind Flay (28+), Devouring Plague (28+), Shadow Word: Death (40+), Power Word: Shield and your heals every visit."}, icons = {"inv_misc_book_09"}}, {level = 60, spells = {"Prayer of Spirit", "Train the new ranks of Shadow Word: Pain, Mind Blast, Mind Flay (28+), Devouring Plague (28+), Shadow Word: Death (40+), Power Word: Shield and your heals every visit."}, notes = {"Group buff.", "Train the new ranks of Shadow Word: Pain, Mind Blast, Mind Flay (28+), Devouring Plague (28+), Shadow Word: Death (40+), Power Word: Shield and your heals every visit."}, icons = {"spell_holy_prayerofspirit", "inv_misc_book_09"}}}, br = {{level = 1, icon = "spell_holy_wordfortitude", title = "Before Talents", range = "Levels 1–9", intro = "Smite and wand early. Every Priest levels on a wand — buy or make the best one you can.", steps = {"Power Word: Fortitude and Inner Fire (12) up.", "Shadow Word: Pain (4), then Smite or wand.", "Power Word: Shield (6) when something reaches you.", "Finish with your wand to save mana."}, stepIcons = {"spell_holy_wordfortitude", "spell_shadow_shadowwordpain", "spell_holy_powerwordshield", "inv_wand_01"}}, {level = 10, icon = "spell_shadow_unholyfrenzy", title = "Mind Blast & Wand", range = "Levels 10–19", intro = "Spirit Tap refills mana after kills. Open with Mind Blast, DoT, then wand.", steps = {"Mind Blast from range → Shadow Word: Pain → wand.", "Shield when it reaches you; the shield also stops spell pushback.", "Psychic Scream (14) when two are on you.", "Controller: the Fight macro on RT+A does this order."}, stepIcons = {"spell_shadow_unholyfrenzy", "spell_holy_powerwordshield", "spell_shadow_psychicscream", "inv_misc_note_01"}}, {level = 20, icon = "spell_shadow_siphonmana", title = "Mind Flay", range = "Levels 20–29", intro = "Mind Flay (20) slows by 50% but reaches only 20 yd (24 with Shadow Reach). Devouring Plague (20) is trainable for every Priest: instant, 24 sec cooldown, heals you.", steps = {"Mind Blast from range → Pain → Mind Flay until it dies.", "Devouring Plague on tough mobs whenever it is off cooldown.", "Vampiric Embrace (25) on tough mobs for self-healing.", "Flash Heal (20) between pulls."}, stepIcons = {"spell_shadow_unholyfrenzy", "spell_shadow_devouringplague", "spell_shadow_unsummonbuilding", "spell_holy_flashheal"}}, {level = 30, icon = "spell_shadow_demonicfortitude", title = "Shadow Word: Death", range = "Levels 30–39", intro = "Shadow Word: Death (32) finishes low mobs — but if they survive it, you take 30% of your max health.", steps = {"Use Death only when the mob will die from it.", "Silence (32) casters.", "Devouring Plague on packs — with Devouring Contagion (30–31) it jumps to 2 enemies within 10 yd when the target dies."}, stepIcons = {"spell_shadow_demonicfortitude", "spell_shadow_impphaseshift", "spell_shadow_devouringplague"}}, {level = 40, icon = "spell_shadow_shadowform", title = "Shadowform", range = "Levels 40–60", intro = "Shadowform (40) halves Shadow spell costs and adds damage. You can't heal in it — Shield and Vampiric Embrace keep you alive.", steps = {"Shadowform on; drop it only to heal between pulls.", "Mind Blast → Pain → Plague → Mind Flay; Mind Blast again every 5.5 sec once Improved Mind Blast is 5/5.", "Shadow Word: Death to finish."}, stepIcons = {"spell_shadow_shadowform", "spell_shadow_shadowwordpain", "spell_shadow_demonicfortitude"}}}, spec = "Shadow", guide = "Shadow Priest"},
  ROGUE = {macros = {{name = "Fight", title = "Fight", icon = "spell_shadow_ritualofsacrifice", lo = 1, hi = 9, body = "#showtooltip\n/startattack\n/castsequence reset=target Sinister Strike, Sinister Strike, Sinister Strike, Eviscerate", pad = "RT+A", kb = "1", tips = {"Each press: Sinister Strike ×3, then Eviscerate.", "\"Not enough energy\": Keep pressing — it waits for Energy, then continues."}}, {name = "Fight", title = "Fight", icon = "ability_rogue_slicedice", lo = 10, hi = 23, body = "#showtooltip\n/startattack\n/castsequence reset=target Sinister Strike, Sinister Strike, Slice and Dice, Sinister Strike, Sinister Strike, Sinister Strike, Eviscerate", pad = "RT+A", kb = "1", tips = {"Each press: SS ×2 → Slice and Dice → SS ×3 → Eviscerate.", "New target: Starts over."}}, {name = "Fight", title = "Fight", icon = "ability_theblackarrow", lo = 24, hi = 60, body = "#showtooltip\n/startattack\n/castsequence reset=target Sinister Strike, Sinister Strike, Slice and Dice, Shank, Sinister Strike, Sinister Strike, Sinister Strike, Eviscerate", pad = "RT+A", kb = "1", tips = {"Each press: SS ×2 → Slice and Dice → Shank (Energy back, no combo point) → SS ×3 → Eviscerate.", "Why Shank is 4th: It has a 10 sec cooldown and the macro waits on it, so it sits mid-fight when your Energy is low and it is always ready.", "New target: Starts over."}}, {name = "Stop a cast", title = "Stop a cast", icon = "ability_kick", lo = 12, hi = 60, body = "#showtooltip\n/castsequence reset=12 Kick, Gouge", pad = "RT+X", kb = "4", tips = {"First press: Kick.", "Second press: Gouge — if Kick missed or they cast again."}}}, plan = {{name = "Efficient Strikes", tree = "Combat", from = 10, to = 11, why = "Sinister Strike is your most-pressed button: 45 Energy drops to 42 now, 40 at 2/2.", more = "", max = 2, icon = "spell_shadow_ritualofsacrifice"}, {name = "Coup de Grace", tree = "Combat", from = 12, to = 14, why = "Eviscerate is your finisher — 20% more damage on every kill.", more = "More Eviscerate damage.", max = 3, icon = "ability_rogue_eviscerate"}, {name = "Deflection", tree = "Combat", from = 15, to = 17, why = "+6% parry: fewer hits taken, and it unlocks Riposte at 20.", more = "+2% more parry.", max = 3, icon = "ability_parry"}, {name = "Precision", tree = "Combat", from = 18, to = 19, why = "Forever Precision is 1% hit per rank (3 max, was 5%). Misses waste Energy.", more = "+1% more hit.", max = 3, icon = "ability_marksmanship"}, {name = "Riposte", tree = "Combat", from = 20, to = 20, why = "After a parry: 10 Energy, 150% weapon damage and a 6 sec disarm (6 sec cooldown). Own button — press it when it lights up.", more = "", max = 1, icon = "ability_warrior_challange"}, {name = "Precision", tree = "Combat", from = 21, to = 21, why = "Precision to 3/3: 3% hit.", more = "", max = 3, icon = "ability_marksmanship"}, {name = "Endurance", tree = "Combat", from = 22, to = 23, why = "Evasion and Sprint cooldowns −30% (−60% at 2/2): both back every 2 min instead of 5.", more = "Both now 2 min.", max = 2, icon = "spell_shadow_shadowward"}, {name = "Improved Sprint", tree = "Combat", from = 24, to = 24, why = "50% chance for Sprint to break snares (100% at 2/2 later).", more = "", max = 2, icon = "ability_rogue_sprint"}, {name = "Aggression", tree = "Combat", from = 25, to = 27, why = "Sinister Strike and Eviscerate deal 15% more — your two main attacks.", more = "+5% more.", max = 3, icon = "ability_racial_avatar"}, {name = "Weapon Expertise", tree = "Combat", from = 28, to = 29, why = "Attacks 1% less likely to be dodged or parried (2% at 2/2). Needs Precision 3/3.", more = "Now 2%.", max = 2, icon = "spell_holy_blessingofstrength"}, {name = "Blade Flurry", tree = "Combat", from = 30, to = 30, why = "Blade Flurry: 25 Energy, 2 min cooldown — +20% attack speed and hits a second mob for 15 sec.", more = "", max = 1, icon = "ability_warrior_punishingblow"}, {name = "Dual Wield Specialization", tree = "Combat", from = 31, to = 32, why = "Off-hand damage +50%. Your off-hand weapon hits on every auto attack.", more = "+25% more.", max = 2, icon = "ability_dualwield"}, {name = "Hack and Slash", tree = "Combat", from = 33, to = 34, why = "Weapon bonus: extra attacks with swords and axes, crit with daggers and fists, armor penetration with maces.", more = "Bigger weapon bonus.", max = 5, icon = "inv_sword_27"}, {name = "Flash of Steel", tree = "Combat", from = 35, to = 39, why = "Shank returns 15 Energy (25 at 44). Each rank adds +3 Energy and −0.4 sec cooldown: 5/5 = +15 Energy, every 8 sec.", more = "+3 Energy, −0.4 sec.", max = 5, icon = "ability_rogue_restlessblades"}, {name = "Adrenaline Rush", tree = "Combat", from = 40, to = 40, why = "The capstone: double Energy regeneration for 15 sec. Pair with Blade Flurry for huge burst.", more = "", max = 1, icon = "spell_shadow_shadowworddominate"}, {name = "Hack and Slash", tree = "Combat", from = 41, to = 43, why = "Finish Hack and Slash for the full weapon bonus.", more = "", max = 5, icon = "inv_sword_27"}, {name = "Flawless Execution", tree = "Combat", from = 44, to = 44, why = "Eviscerate costs 20 Energy instead of 35.", more = "", max = 1, icon = "inv_sword_35"}, {name = "Malice", tree = "Assassination", from = 45, to = 49, why = "Combat is done. +5% crit from the Assassination tree.", more = "+1% more crit.", max = 5, icon = "ability_racial_bloodrage"}, {name = "Remorseless Attacks", tree = "Assassination", from = 50, to = 51, why = "After a kill, your next Sinister Strike within 20 sec gets +20% crit (+40% at 2/2) — good for chain-pulling.", more = "", max = 2, icon = "ability_fiegndead"}, {name = "Improved Slice and Dice", tree = "Assassination", from = 52, to = 54, why = "Slice and Dice lasts 45% longer.", more = "Longer Slice and Dice.", max = 3, icon = "ability_rogue_slicedice"}, {name = "Lethality", tree = "Assassination", from = 55, to = 56, why = "Sinister Strike crits hit 20% harder.", more = "", max = 2, icon = "ability_criticalstrike"}, {name = "Vigor", tree