ue_feint", "ability_rogue_rupture", "ability_backstab"}}}, br = {{level = 1, icon = "spell_shadow_ritualofsacrifice", title = "Before Talents", range = "Levels 1–9", intro = "Sinister Strike to build combo points, Eviscerate to spend them. Energy refills smoothly in Forever — 10 a second, no ticks to wait for.", steps = {"Sinister Strike ×3, then Eviscerate.", "Stealth up to a mob, then open with Sinister Strike.", "Gouge (6) to stop a caster or buy time to bandage.", "Evasion (8) when a fight goes wrong."}, stepIcons = {"spell_shadow_ritualofsacrifice", "ability_stealth", "ability_gouge", "spell_shadow_shadowward"}}, {level = 10, icon = "ability_rogue_slicedice", title = "Slice and Dice", range = "Levels 10–19", intro = "Slice and Dice speeds up your attacks. Put it up at 2 combo points, then build for Eviscerate.", steps = {"Sinister Strike ×2 → Slice and Dice → Sinister Strike ×3 → Eviscerate.", "Kick (12) casters.", "Sprint (10) away from a bad pull.", "Controller: the Fight macro on RT+A does this order for you."}, stepIcons = {"ability_rogue_slicedice", "ability_kick", "ability_rogue_sprint", "inv_misc_note_01"}}, {level = 20, icon = "ability_warrior_challange", title = "Riposte & Poisons", range = "Levels 20–29", intro = "Riposte (20) lights up after a parry. Poisons arrive at 20 — coat your main hand with Instant Poison.", steps = {"Riposte every time it lights up.", "Instant Poison on your weapons — reapply after 30 min or when the charges run out.", "Vanish (22) to escape a fight you can't win.", "Shank (24): off-hand strike that gives back Energy — the 24+ Fight macro uses it.", "Cheap Shot (26) from Stealth on tough mobs."}, stepIcons = {"ability_warrior_challange", "ability_poisons", "ability_vanish", "ability_theblackarrow", "ability_cheapshot"}}, {level = 30, icon = "ability_warrior_punishingblow", title = "Blade Flurry", range = "Levels 30–39", intro = "Blade Flurry (30) hits two mobs at once. Deadly Poison (30) goes on your off-hand.", steps = {"Two mobs? Blade Flurry, then Fight.", "Kidney Shot (30) on a dangerous mob.", "Blind (34) a second mob while you kill the first.", "Deadly Poison on the off-hand, Instant on the main hand."}, stepIcons = {"ability_warrior_punishingblow", "ability_rogue_kidneyshot", "spell_shadow_mindsteal", "ability_rogue_dualweild"}}, {level = 40, icon = "spell_shadow_shadowworddominate", title = "Adrenaline Rush", range = "Levels 40–60", intro = "Adrenaline Rush (40) doubles Energy regen for 15 sec. With Blade Flurry it melts packs.", steps = {"Big pull: Blade Flurry + Adrenaline Rush, then Fight.", "Shank rank 2 (44) + Flash of Steel 5/5: 40 Energy back for 5, every 8 sec — the Fight macro fires it.", "Evasion every 2 min with Endurance."}, stepIcons = {"spell_shadow_shadowworddominate", "ability_theblackarrow", "spell_shadow_shadowward"}}}, spec = "Combat", guide = "Combat Rogue"},
  SHAMAN = {macros = {{name = "Fight", title = "Fight", icon = "spell_nature_earthshock", lo = 4, hi = 9, body = "#showtooltip\n/startattack\n/castsequence reset=target Lightning Bolt, Earth Shock, Earth Shock", pad = "RT+A", kb = "1", tips = {"Each press: Lightning Bolt to pull, then Earth Shock twice, then it starts over. You keep swinging.", "\"Not ready\": Earth Shock is on cooldown — press again in a moment."}}, {name = "Fight", title = "Fight", icon = "spell_fire_flameshock", lo = 10, hi = 24, body = "#showtooltip\n/startattack\n/castsequence reset=target Flame Shock, Earth Shock, Earth Shock", pad = "RT+A", kb = "1", tips = {"Each press: Flame Shock, then Earth Shock on every cooldown.", "New target: Starts over with Flame Shock."}}, {name = "Fight", title = "Fight", icon = "ability_shaman_stormstrike", lo = 25, hi = 60, body = "#showtooltip\n/startattack\n/castsequence reset=target Flame Shock, Stormstrike, Earth Shock, Stormstrike", pad = "RT+A", kb = "1", tips = {"Each press: Flame Shock → Stormstrike → Earth Shock (+20% from Stormstrike) → Stormstrike → repeat. Shocks share one 6 sec cooldown, so a shock and a Stormstrike alternate with no idle wait; Flame Shock comes back every 12 sec.", "\"Not ready\": The next step is on cooldown or you lack mana — keep pressing, you keep swinging. Out of mana for a shock, the sequence waits there."}}, {name = "Totems", title = "Totems", icon = "spell_fire_searingtotem", lo = 10, hi = 60, body = "#showtooltip\n/cast Call of the Elements\n/cast Searing Totem", pad = "RT+X", kb = "3", tips = {"Before 20: Searing Totem.", "From 20: One 3 sec cast drops all 4 totems from your Totem Bar: Strength of Earth, Searing, Mana Spring (26), Grace of Air (42). They last 5 min; Searing only 30–55 sec."}}, {name = "Pack", title = "Pack", icon = "spell_nature_chainlightning", lo = 32, hi = 60, body = "#showtooltip\n/startattack\n/castsequence reset=target Fire Nova, Chain Lightning", pad = "RT+B", kb = "2", tips = {"When: 3+ mobs, with a fire totem down next to them.", "Each press: Fire Nova (10 sec cooldown) → Chain Lightning (6 sec cooldown) → repeat; it waits on Fire Nova's cooldown."}}, {name = "Heal up", title = "Heal up", icon = "spell_nature_healingwavelesser", lo = 1, hi = 60, body = "#showtooltip\n/cast [@player] Lesser Healing Wave\n/cast [@player] Healing Wave", pad = "LT+A", kb = "Q", tips = {"One press: Lesser Healing Wave from 20, Healing Wave before. Heals you even with an enemy targeted."}}, {name = "Imbue", title = "Imbue", icon = "spell_nature_cyclone", lo = 1, hi = 60, body = "#showtooltip\n/cast Windfury Weapon\n/cast Rockbiter Weapon", pad = "LT+→", kb = "Shift+1", tips = {"One press: Windfury Weapon from 30, Rockbiter before."}}}, plan = {{name = "Thundering Strikes", tree = "Enhancement", from = 10, to = 14, why = "+1% crit per point with melee, shocks and bolts — +5% by 14. Every melee crit will trigger Flurry later.", more = "+1% more crit.", max = 5, icon = "ability_thunderbolt"}, {name = "Mental Dexterity", tree = "Enhancement", from = 15, to = 17, why = "Attack Power equal to 50% of your Intellect, 150% at 3/3. Intellect gear now hits harder. Flurry needs this maxed.", more = "+50% more of your Intellect.", max = 3, icon = "spell_nature_mentalquickness"}, {name = "Ancestral Knowledge", tree = "Enhancement", from = 18, to = 19, why = "+Intellect: more mana and, through Mental Dexterity, more Attack Power.", more = "+2% more.", max = 5, icon = "spell_shadow_grimward"}, {name = "Shamanistic Focus", tree = "Enhancement", from = 20, to = 20, why = "Shocks and Lightning Shield cost 45% less mana — you can shock on every 6 sec cooldown.", more = "", max = 1, icon = "spell_nature_elementalabsorption"}, {name = "Elemental Weapons", tree = "Enhancement", from = 21, to = 23, why = "Rockbiter's Attack Power +7% per point (+20% at 3/3); at 3/3 Windfury is 40% stronger from 30 and Flametongue 15%.", more = "Stronger weapon imbues.", max = 3, icon = "spell_fire_flametounge"}, {name = "Ancestral Knowledge", tree = "Enhancement", from = 24, to = 24, why = "One more Intellect point to open row 4 for Stormstrike.", more = "", max = 5, icon = "spell_shadow_grimward"}, {name = "Stormstrike", tree = "Enhancement", from = 25, to = 25, why = "Stormstrike: a 150% weapon hit every 6 sec for 8% of base mana; your next Earth Shock within 12 sec deals 20% more. Your main button from here.", more = "", max = 1, icon = "ability_shaman_stormstrike"}, {name = "Flurry", tree = "Enhancement", from = 26, to = 30, why = "After a melee crit your next 3 swings are 6% faster per point — 30% at 5/5.", more = "+6% more.", max = 5, icon = "ability_ghoulfrenzy"}, {name = "Improved Stormstrike", tree = "Enhancement", from = 31, to = 32, why = "50% chance per Stormstrike of 50% mana regen while casting for 15 sec, and a 50% chance a dodge or parry resets its cooldown.", more = "Now 100% for both.", max = 2, icon = "spell_shaman_improvedstormstrike"}, {name = "Mental Quickness", tree = "Enhancement", from = 33, to = 34, why = "Spell damage +15% of your Intellect, 30% at 2/2 — bigger shocks and bolts. Rage of the Farseer requires it.", more = "30% of your Intellect.", max = 2, icon = "spell_nature_sleep"}, {name = "Maelstrom Weapon", tree = "Enhancement", from = 35, to = 39, why = "Melee hits have a chance to stack it (up to 5, 30 sec). Each stack is 4% per point: at 5/5 and 5 stacks, Lightning Bolt is instant and free.", more = "+4% more per stack.", max = 5, icon = "spell_shaman_maelstromweapon"}, {name = "Rage of the Farseer", tree = "Enhancement", from = 40, to = 40, why = "The capstone: +30% attack speed for 25 sec, 3 min cooldown. Use it on elites and big pulls.", more = "", max = 1, icon = "spell_nature_bloodlust"}, {name = "Improved Ghost Wolf", tree = "Enhancement", from = 41, to = 42, why = "Ghost Wolf's 3 sec cast drops to 2 sec and works indoors.", more = "Now instant — less time walking.", max = 2, icon = "spell_nature_spiritwolf"}, {name = "Spirit Weapons", tree = "Enhancement", from = 43, to = 43, why = "Parry chance, so Improved Stormstrike resets more often. 30% less threat on Windfury (30% more on Rockbiter).", more = "", max = 1, icon = "ability_parry"}, {name = "Ancestral Knowledge", tree = "Enhancement", from = 44, to = 45, why = "Ancestral Knowledge to 5/5.", more = "+2% more.", max = 5, icon = "spell_shadow_grimward"}, {name = "Anticipation", tree = "Enhancement", from = 46, to = 48, why = "+2% dodge per point, 6% by 48: fewer hits taken and more Stormstrike resets. Enhancement is done.", more = "+2% more.", max = 3, icon = "spell_nature_mirrorimage"}, {name = "Tidal Focus", tree = "Restoration", from = 49, to = 52, why = "Restoration row 1: +1% hit per point with melee and spells — 4% by 52.", more = "+1% more hit.", max = 5, icon = "spell_frost_manarecharge"}, {name = "Concussion", tree = "Elemental", from = 53, to = 57, why = "Elemental row 1: Earth Shock, Lightning Bolt and Chain Lightning deal 1% more per point — 5% by 57.", more = "+1% more.", max = 5, icon = "spell_nature_earthshock"}, {name = "Elemental Devastation", tree = "Elemental", from = 58, to = 60, why = "Shock and bolt crits give +3% melee crit per point for 10 sec — 9% by 60.", more = "+3% more.", max = 3, icon = "spell_fire_elementaldevastation"}}, train = {{level = 1, spells = {"Healing Wave", "Lightning Bolt", "Rockbiter Weapon"}, notes = {"Your heal between pulls.", "Pull from range.", "Weapon imbue until 30."}, icons = {"spell_nature_magicimmunity", "spell_nature_lightning", "spell_nature_rockbiter"}}, {level = 4, spells = {"Earth Shock", "Stoneskin Totem"}, notes = {"Your main shock — also interrupts.", "Earth totem."}, icons = {"spell_nature_earthshock", "spell_nature_stoneskintotem"}}, {level = 6, spells = {"Earthbind Totem", "Train every new rank each visit: shocks, bolts, heals, totems, Fire Nova, Lightning Shield, imbues."}, notes = {"Slows — escapes.", "Train every new rank each visit: shocks, bolts, heals, totems, Fire Nova, Lightning Shield, imbues."}, icons = {"spell_nature_strengthofearthtotem02", "inv_misc_book_09"}}, {level = 8, spells = {"Lightning Shield", "Stoneclaw Totem", "Train every new rank each visit: shocks, bolts, heals, totems, Fire Nova, Lightning Shield, imbues."}, notes = {"Keep it up always.", "Pulls a mob off you.", "Train every new rank each visit: shocks, bolts, heals, totems, Fire Nova, Lightning Shield, imbues."}, icons = {"spell_nature_lightningshield", "spell_nature_stoneclawtotem", "inv_misc_book_09"}}, {level = 10, spells = {"Flame Shock", "Searing Totem", "Strength of Earth Totem", "Flametongue Weapon"}, notes = {"Opener with a burn.", "Extra damage; lasts 30–55 sec, unlike your 5 min totems.", "Strength — your earth totem.", "The alternative imbue to Rockbiter. Imbues last 60 min now."}, icons = {"spell_fire_flameshock", "spell_fire_searingtotem", "spell_nature_earthbindtotem", "spell_fire_flametounge"}}, {level = 12, spells = {"Fire Nova", "Purge", "Ancestral Spirit", "Train every new rank each visit: shocks, bolts, heals, totems, Fire Nova, Lightning Shield, imbues."}, notes = {"A spell now: instant AoE around your fire totem, 10 sec cooldown.", "Remove enemy buffs.", "Resurrect.", "Train every new rank each visit: shocks, bolts, heals, totems, Fire Nova, Lightning Shield, imbues."}, icons = {"spell_fire_sealoffire", "spell_nature_purge", "spell_nature_regenerate", "inv_misc_book_09"}}, {level = 14, spells = {"Train every new rank each visit: shocks, bolts, heals, totems, Fire Nova, Lightning Shield, imbues."}, notes = {"Train every new rank each visit: shocks, bolts, heals, totems, Fire Nova, Lightning Shield, imbues."}, icons = {"inv_misc_book_09"}}, {level = 16, spells = {"Cure Poison", "Train every new rank each visit: shocks, bolts, heals, totems, Fire Nova, Lightning Shield, imbues."}, notes = {"Utility.", "Train every new rank each visit: shocks, bolts, heals, totems, Fire Nova, Lightning Shield, imbues."}, icons = {"spell_nature_nullifypoison", "inv_misc_book_09"}}, {level = 18, spells = {"Tremor Totem", "Train every new rank each visit: shocks, bolts, heals, totems, Fire Nova, Lightning Shield, imbues."}, notes = {"Fear immunity.", "Train every new rank each visit: shocks, bolts, heals, totems, Fire Nova, Lightning Shield, imbues."}, icons = {"spell_nature_tremortotem", "inv_misc_book_09"}}, {level = 20, spells = {"Call of the Elements", "Ghost Wolf", "Lesser Healing Wave", "Totemic Recall", "Frost Shock", "Healing Stream Totem", "Frostbrand Weapon", "Train every new rank each visit: shocks, bolts, heals, totems, Fire Nova, Lightning Shield, imbues."}, notes = {"Drops every totem on your Totem Bar in one 3 sec cast. Most last 5 min now.", "Travel form — a 3 sec cast until Improved Ghost Wolf.", "Fast heal.", "Picks your totems up and returns 25% of their mana.", "Slows runners.", "Water totem.", "PvP.", "Train every new rank each visit: shocks, bolts, heals, totems, Fire Nova, Lightning Shield, imbues."}, icons = {"spell_shaman_dropall_01", "spell_nature_spiritwolf", "spell_nature_healingwavelesser", "spell_shaman_totemrecall", "spell_frost_frostshock", "inv_spear_04", "spell_frost_frostbrand", "inv_misc_book_09"}}, {level = 22, spells = {"Cure Disease", "Poison Cleansing Totem", "Totemic Call", "Water Breathing", "Train every new rank each visit: shocks, bolts, heals, totems, Fire Nova, Lightning Shield, imbues."}, notes = {"Utility.", "Groups.", "Teleports your totems to you. 30 sec cooldown.", "Utility.", "Train every new rank each visit: shocks, bolts, heals, totems, Fire Nova, Lightning Shield, imbues."}, icons = {"spell_nature_removedisease", "spell_nature_poisoncleansingtotem", "ability_shaman_totemrelocation", "spell_shadow_demonbreath", "inv_misc_book_09"}}, {level = 24, spells = {"Frost Resistance Totem", "Train every new rank each visit: shocks, bolts, heals, totems, Fire Nova, Lightning Shield, imbues."}, notes = {"Situational.", "Train every new rank each visit: shocks, bolts, heals, totems, Fire Nova, Lightning Shield, imbues."}, icons = {"spell_frostresistancetotem_01", "inv_misc_book_09"}}, {level = 26, spells = {"Mana Spring Totem", "Magma Totem", "Far Sight", "Train every new rank each visit: shocks, bolts, heals, totems, Fire Nova, Lightning Shield, imbues."}, notes = {"Your water totem.", "Packs.", "Utility.", "Train every new rank each visit: shocks, bolts, heals, totems, Fire Nova, Lightning Shield, imbues."}, icons = {"spell_nature_manaregentotem", "spell_fire_selfdestruct", "spell_nature_farsight", "inv_misc_book_09"}}, {level = 28, spells = {"Flametongue Totem", "Fire Resistance Totem", "Water Walking", "Train every new rank each visit: shocks, bolts, heals, totems, Fire Nova, Lightning Shield, imbues."}, notes = {"Groups.", "Situational.", "Utility.", "Train every new rank each visit: shocks, bolts, heals, totems, Fire Nova, Lightning Shield, imbues."}, icons = {"spell_nature_guardianward", "spell_fireresistancetotem_01", "spell_frost_windwalkon", "inv_misc_book_09"}}, {level = 30, spells = {"Windfury Weapon", "Reincarnation", "Astral Recall", "Grounding Totem", "Call of the Ancestors", "Nature Resistance Totem", "Train every new rank each visit: shocks, bolts, heals, totems, Fire Nova, Lightning Shield, imbues."}, notes = {"The big spike: 20% chance per hit for 2 extra attacks — best on a slow two-hander.", "Come back from death.", "A second hearthstone.", "Eats a spell — casters.", "A second totem set.", "Situational.", "Train every new rank each visit: shocks, bolts, heals, totems, Fire Nova, Lightning Shield, imbues."}, icons = {"spell_nature_cyclone", "spell_nature_reincarnation", "spell_nature_astralrecal", "spell_nature_groundingtotem", "spell_shaman_dropall_02", "spell_nature_natureresistancetotem", "inv_misc_book_09"}}, {level = 32, spells = {"Chain Lightning", "Windfury Totem", "Train every new rank each visit: shocks, bolts, heals, totems, Fire Nova, Lightning Shield, imbues."}, notes = {"Packs: 3 targets, 2.5 sec cast, 6 sec cooldown.", 